using System;using System.IO;using System.Linq;using System.Collections.Generic;using UnityEngine;using UnityEditor;using Object=UnityEngine.Object;
public static class CorrectGarmentClearance {public static object Main(){if(EditorApplication.isPlayingOrWillChangePlaymode)throw new Exception("Edit required");const string folder="Assets/ShooterSurvival/Models/Chapters/Chapters45/DetailedCharacters20261003/CH06R/";string backup="outputs/chapter45-detailed-design-2026-10-03/recovery/garment-fit/garment-clearance-before-mask-fix.asset";if(File.Exists(backup))throw new Exception("Already fixed");File.Copy(folder+"garment-clearance.asset",backup,false);var p=PrefabUtility.LoadPrefabContents(folder+"CH06R.prefab");try{var skin=p.GetComponentInChildren<SkinnedMeshRenderer>();var original=AssetDatabase.LoadAssetAtPath<GameObject>(folder+"body.fbx").GetComponentInChildren<SkinnedMeshRenderer>().sharedMesh;var mesh=AssetDatabase.LoadAssetAtPath<Mesh>(folder+"garment-clearance.asset");var raw=new Texture2D(2,2,TextureFormat.RGBA32,false);raw.LoadImage(File.ReadAllBytes(AssetDatabase.GetAssetPath(skin.sharedMaterial.GetTexture("_BaseMap"))));var verts=original.vertices;var uv=original.uv;var groups=new HashSet<Vector3>();for(int i=0;i<verts.Length;i++){var pos=p.transform.InverseTransformPoint(skin.transform.TransformPoint(verts[i]));var c=raw.GetPixelBilinear(uv[i].x,uv[i].y);if(pos.y>.42f&&pos.y<1.05f&&c.g>c.r*1.09f&&c.b>c.r*1.13f&&c.r<.65f)groups.Add(verts[i]);}var selected=Enumerable.Range(0,verts.Length).Where(i=>groups.Contains(verts[i])).ToArray();float center=selected.Average(i=>p.transform.InverseTransformPoint(skin.transform.TransformPoint(verts[i])).z);float maxDelta=0;foreach(int i in selected){var pos=p.transform.InverseTransformPoint(skin.transform.TransformPoint(verts[i]));float lower=1-Mathf.SmoothStep(0,1,Mathf.InverseLerp(.75f,1.03f,pos.y));float front=Mathf.SmoothStep(0,1,Mathf.InverseLerp(center-.04f,center+.04f,pos.z));var delta=new Vector3(Mathf.Sign(pos.x)*.018f*lower,0,.09f*front*lower);maxDelta=Mathf.Max(maxDelta,delta.magnitude);verts[i]+=skin.transform.InverseTransformVector(p.transform.TransformVector(delta));}mesh.vertices=verts;mesh.RecalculateBounds();EditorUtility.SetDirty(mesh);Object.DestroyImmediate(raw);AssetDatabase.SaveAssets();return new{vertices=selected.Length,maxDelta,sourceMesh=AssetDatabase.GetAssetPath(original),uvSeamDuplicatesKeptTogether=true,reason="Correct normalized smoothstep mask; replace from preserved original vertices rather than accumulating offsets."};}finally{PrefabUtility.UnloadPrefabContents(p);}}}
